function showPage(page){state.page=page;["library","template","batch"].forEach(p=>$(p+"Page").hidden=p!==page);document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.page===page));if(page==="batch")renderCombos();if(page==="template")draw()}
function makeAsset(type,file,source="file",id=crypto.randomUUID(),relativePath=""){const asset={id,type,name:file.name,file,source,relativePath,url:URL.createObjectURL(file),img:null,alphaBounds:null};const img=new Image();img.onload=()=>{asset.img=img;asset.alphaBounds=readAlphaBounds(img);renderIntentPreview()};img.src=asset.url;return asset}
