function addAssets(type,files){pushGlobalHistory();const keys=new Set(state.assets[type].map(a=>`${a.name}|${a.file.size}|${a.file.lastModified}`));let count=0;files.forEach(file=>{const key=`${file.name}|${file.size}|${file.lastModified}`;if(keys.has(key))return;state.assets[type].push(makeAsset(type,file));keys.add(key);count++});renderAssets();renderCombos();toast(`已添加 ${count} 个${type==="main"?"主品":"赠品"}`)}
async function walkDirectory(handle,path=""){const out=[];for await(const entry of handle.values()){const relative=path?`${path}/${entry.name}`:entry.name;if(entry.kind==="directory")out.push(...await walkDirectory(entry,relative));else out.push({file:await entry.getFile(),relativePath:relative})}return out}
