async function chooseProductLibrary(){if(!window.showDirectoryPicker)return toast("请使用最新版 Chrome 或 Edge 打开网站");try{state.folders.products=await window.showDirectoryPicker({mode:"read"});await rememberFolder("products",state.folders.products);await refreshProductLibrary()}catch(e){if(e.name!=="AbortError")toast("读取商品素材库失败："+e.message)}}
