async function chooseTemplateLibrary(){if(!window.showDirectoryPicker)return toast("请使用最新版 Chrome 或 Edge 打开网站");try{state.folders.templates=await window.showDirectoryPicker({mode:"read"});await rememberFolder("templates",state.folders.templates);await refreshTemplateLibrary()}catch(e){if(e.name!=="AbortError")toast("读取背景模板库失败："+e.message)}}
async function refreshTemplateLibrary(){const handle=state.folders.templates;if(!handle)return;try{if((await handle.requestPermission({mode:"read"}))!=="granted")return toast("没有获得背景模板库读取权限");const records=await walkDirectory(handle),map=new Map();records.forEach(r=>{const m=r.relativePath.match(/^(.*)\.([^.]+)$/);if(!m)return;const ext=m[2].toLowerCase();if(!["png","jpg","jpeg","webp","psd","psb"].includes(ext))return;const key=m[1].toLowerCase(),pair=map.get(key)||{key:m[1],preview:null,psd:null};if(["psd","psb"].includes(ext))pair.psd=r;else if(!pair.preview||ext==="png")pair.preview=r;map.set(key,pair)});state.templatePairs.forEach(p=>{if(p.previewUrl)URL.revokeObjectURL(p.previewUrl)});state.templatePairs=[...map.values()].filter(p=>p.preview||p.psd).sort((a,b)=>a.key.localeCompare(b.key,"zh-CN",{numeric:true}));renderTemplatePairs();$("templateLibraryStatus").textContent=`已连接：${handle.name} · 完整配对 ${state.templatePairs.filter(p=>p.preview&&p.psd).length} 组 · 共 ${state.templatePairs.length} 项`;$("templateLibraryStatus").classList.add("connected");$("templateLibraryRefresh").disabled=false;toast("背景模板库已读取") }catch(e){toast("刷新背景模板库失败："+e.message)}}
