async function selectTemplatePair(value,apply=true){const p=value===""?null:state.templatePairs[Number(value)],info=$("templatePairInfo");syncTemplatePairSelection(value);if(!p){info.textContent="";info.className="pair-info";return}info.textContent=`预览：${p.preview?.file.name||"缺少"}　PSD：${p.psd?.file.name||"缺少"}`;info.className=`pair-info ${p.preview&&p.psd?"ok":"warn"}`;if(!apply||!p.preview||!p.psd)return;if($("templateName").value==="商品图模板")$("templateName").value=p.key.split("/").pop();setPreview(p.preview.file);await setPsdFile(p.psd.file);toast(`已载入模板：${p.key}`)}
function folderDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open("product-layout-folders",1);req.onupgradeneeded=()=>req.result.createObjectStore("handles");req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
