function setAssetCategory(type,category){state.assetFilters[type]=category;if(type==="main")state.assetFilters.gift=matchingGiftCategory(category)}
function renderAssets(){["main","gift"].forEach(type=>{const all=state.assets[type],cats=[...new Set(all.map(a=>assetCategory(a,type)))],filter=state.assetFilters[type];if(filter&&!cats.includes(filter))state.assetFilters[type]="";const catBox=$(type+"Categories");catBox.innerHTML=`<button data-category="" data-type="${type}" class="${state.assetFilters[type]?"":"active"}">全部 ${all.length}</button>`+cats.map(c=>`<button data-category="${escapeHtml(c)}" data-type="${type}" class="${state.assetFilters[type]===c?"active":""}">${escapeHtml(c)} ${all.filter(a=>assetCategory(a,type)===c).length}</button>`).join("");const list=state.assetFilters[type]?all.filter(a=>assetCategory(a,type)===state.assetFilters[type]):all,box=$(type+"Assets");box.innerHTML=list.length?list.map(a=>`<article class="asset"><img src="${a.url}"><div><span title="${escapeHtml(a.relativePath||a.name)}">${escapeHtml(a.name)}</span><button data-remove="${a.id}" data-type="${type}">×</button></div><small>${escapeHtml(assetCategory(a,type))}${a.inferredRole?" · 自动归入主品":""}</small></article>`).join(""):`<div class="empty">尚未添加${type==="main"?"主品":"赠品"}</div>`});document.querySelectorAll("[data-category]").forEach(b=>b.onclick=()=>{setAssetCategory(b.dataset.type,b.dataset.category);renderAssets()});document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>removeAsset(b.dataset.type,b.dataset.remove))}
