function validate(){const errors=[];if(!state.psd)errors.push("未选择 PSD 模板");if(!state.preview)errors.push("未选择模板预览图");if(state.psd&&!state.psdMeta)errors.push("无法读取 PSD/PSB 的实际尺寸");if(state.psdMeta&&state.preview&&Math.abs(state.psdMeta.width/state.psdMeta.height-state.canvasW/state.canvasH)>=.001)errors.push(`PSD 实际比例 ${state.psdMeta.width}×${state.psdMeta.height} 与预览图 ${state.canvasW}×${state.canvasH} 不一致`);if(state.needsText&&state.psd){const scan=state.psdTextScan;if(scan.status==="scanning")errors.push("PSD 可变文字图层仍在识别中");if(scan.status==="error")errors.push(`PSD 可变文字识别失败：${scan.error}`);if(scan.status==="done"&&scan.groups!==1)errors.push(`PSD 中应有且仅有 1 个“可变文字”组，当前识别到 ${scan.groups} 个`);if(scan.status==="done"&&!scan.layers.length)errors.push("PSD 的“可变文字”组内没有文字图层");if(scan.duplicates.length)errors.push(`PSD 的“可变文字”组存在重名图层：${scan.duplicates.join("、")}`)}if(!state.zones.main)errors.push("未绘制主品排列区域");if(!state.zones.gift)errors.push("未绘制赠品排列区域");if(!state.zones.mask)errors.push("未绘制整体产品蒙版");state.combos.forEach((c,i)=>{if(!c.main.length)errors.push(`组合 ${i+1} 没有选择主品`)});return errors}
function openExport(){const errors=validate(),box=$("exportCheck");box.className="export-check "+(errors.length?"bad":"ok");box.innerHTML=errors.length?`<strong>暂时不能导出</strong><br>${errors.join("<br>")}`:`<strong>任务检查通过</strong><br>${state.combos.length} 个组合将生成 ${state.combos.length} 个画板，尺寸均为 ${state.canvasW} × ${state.canvasH} px`;$("writeTask").disabled=errors.length>0;$("exportDialog").showModal()}
